/*
 * prog29_roman_numeral_parser.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 *
 * Behaviour (deduced from the obfuscated binary):
 *
 *   • Exactly one command‑line argument is expected – a Roman numeral.
 *   • The argument may be mixed case; it is converted to upper‑case.
 *   • If the argument is empty, longer than 63 characters, contains any
 *     character other than I V X L C D M, or violates the classic Roman‑
 *     numeral syntax (up to 3999), the program prints the single line
 *     "INVALID\n" and exits with status 0.
 *   • Otherwise it prints the decimal value of the numeral followed by a
 *     newline (using printf("%d\n", value);).
 *
 * The validation follows the standard Roman‑numeral rules:
 *
 *   – I, X, C and M may be repeated at most three times consecutively.
 *   – V, L and D may never be repeated.
 *   – A smaller‑value symbol may precede a larger‑value symbol only as a
 *     *subtractive* pair, and only the following pairs are allowed:
 *         I before V or X
 *         X before L or C
 *         C before D or M
 *   – No other subtractive combinations are permitted.
 *
 * The implementation below reproduces those rules exactly, matching the
 * observable output of the original binary.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

/* Return the decimal value of a single Roman symbol, or -1 for an illegal
   character. */
static int value_of(char c)
{
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return -1;
    }
}

/* True if (prev, cur) forms a legal subtractive pair. */
static int is_valid_subtractive(char prev, char cur)
{
    if (prev == 'I' && (cur == 'V' || cur == 'X')) return 1;
    if (prev == 'X' && (cur == 'L' || cur == 'C')) return 1;
    if (prev == 'C' && (cur == 'D' || cur == 'M')) return 1;
    return 0;
}

/*
 * Parse a Roman numeral that is already in upper case.
 * On success, *out_val receives the integer value and the function returns 0.
 * On any validation error, the function returns -1.
 */
static int parse_roman(const char *s, int *out_val)
{
    int total = 0;
    int i = 0;
    int repeat = 1;          /* consecutive repetitions of the same symbol */
    char prev = 0;
    int prev_val = 0;

    while (s[i]) {
        char cur = s[i];
        int cur_val = value_of(cur);
        if (cur_val < 0)               /* illegal character */
            return -1;

        /* ---- Repetition rules ---- */
        if (cur == prev) {
            /* V, L, D may never repeat */
            if (cur == 'V' || cur == 'L' || cur == 'D')
                return -1;
            repeat++;
            if (repeat > 3)            /* I, X, C, M may repeat at most 3 times */
                return -1;
        } else {
            repeat = 1;
        }

        /* ---- Subtractive handling ---- */
        if (prev && prev_val < cur_val) {
            /* A subtractive pair must consist of a single smaller symbol
               directly before a larger one; the smaller symbol must not have
               been repeated. */
            if (repeat != 1)               /* cannot subtract after a repeat */
                return -1;
            if (!is_valid_subtractive(prev, cur))
                return -1;

            /* Remove the value that was previously added for the smaller
               symbol and add the correct pair value. */
            total -= prev_val;
            total += (cur_val - prev_val);
        } else {
            total += cur_val;
        }

        prev = cur;
        prev_val = cur_val;
        i++;
    }

    *out_val = total;
    return 0;
}

int main(int argc, char **argv)
{
    /* ---- Argument count check ---- */
    if (argc != 2) {
        puts("INVALID");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);

    /* ---- Length constraints (original binary limited to 63 chars) ---- */
    if (len == 0 || len > 63) {
        puts("INVALID");
        return 0;
    }

    /* ---- Convert to upper case into a temporary buffer ---- */
    char *buf = malloc(len + 1);
    if (!buf) return 1;               /* allocation failure – not expected */
    for (size_t i = 0; i < len; ++i)
        buf[i] = (char)toupper((unsigned char)input[i]);
    buf[len] = '\0';

    int value;
    if (parse_roman(buf, &value) != 0) {
        puts("INVALID");
        free(buf);
        return 0;
    }

    printf("%d\n", value);
    free(buf);
    return 0;
}
